//! Heartbeat cadence and liveness timeout.
//!
//! Heartbeats are generated by the Engine tick, so their arrival proves the
//! peer's Engine is alive, not just its QUIC stack (transport ACKs would keep
//! a connection alive even if the peer's logic were wedged). Every valid frame
//! from the peer counts as a sign of life.

use std::time::{Duration, Instant};

/// Default interval between heartbeats.
pub const HEARTBEAT_INTERVAL: Duration = Duration::from_millis(250);
/// Default silence after which the peer is considered gone.
pub const HEARTBEAT_TIMEOUT: Duration = Duration::from_millis(1500);

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct HeartbeatMonitor {
    interval: Duration,
    timeout: Duration,
    last_sent: Option<Instant>,
    last_rx: Instant,
}

impl HeartbeatMonitor {
    /// A monitor that considers the peer alive as of `now` and wants to send
    /// its first heartbeat immediately.
    pub fn new(now: Instant, interval: Duration, timeout: Duration) -> HeartbeatMonitor {
        HeartbeatMonitor {
            interval,
            timeout,
            last_sent: None,
            last_rx: now,
        }
    }

    /// `new` with the default 250 ms / 1500 ms timings.
    pub fn with_defaults(now: Instant) -> HeartbeatMonitor {
        HeartbeatMonitor::new(now, HEARTBEAT_INTERVAL, HEARTBEAT_TIMEOUT)
    }

    /// True when a heartbeat should be sent now.
    pub fn due(&self, now: Instant) -> bool {
        match self.last_sent {
            None => true,
            Some(t) => now.saturating_duration_since(t) >= self.interval,
        }
    }

    pub fn on_sent(&mut self, now: Instant) {
        self.last_sent = Some(now);
    }

    /// Call for every valid frame received from the peer, on any channel.
    pub fn on_received(&mut self, now: Instant) {
        if now > self.last_rx {
            self.last_rx = now;
        }
    }

    /// True when nothing arrived for at least the timeout.
    pub fn timed_out(&self, now: Instant) -> bool {
        now.saturating_duration_since(self.last_rx) >= self.timeout
    }

    pub fn last_received(&self) -> Instant {
        self.last_rx
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    const MS: Duration = Duration::from_millis(1);

    #[test]
    fn due_boundaries() {
        let t0 = Instant::now();
        let mut h = HeartbeatMonitor::with_defaults(t0);
        assert!(h.due(t0), "first heartbeat is due immediately");
        h.on_sent(t0);
        assert!(!h.due(t0 + 249 * MS));
        assert!(h.due(t0 + 250 * MS));
        h.on_sent(t0 + 260 * MS);
        assert!(!h.due(t0 + 509 * MS));
        assert!(h.due(t0 + 510 * MS));
    }

    #[test]
    fn timeout_boundaries() {
        let t0 = Instant::now();
        let mut h = HeartbeatMonitor::with_defaults(t0);
        assert!(!h.timed_out(t0 + 1499 * MS));
        assert!(h.timed_out(t0 + 1500 * MS));
        h.on_received(t0 + 1000 * MS);
        assert!(!h.timed_out(t0 + 2499 * MS));
        assert!(h.timed_out(t0 + 2500 * MS));
        // An older timestamp never moves the deadline backwards.
        h.on_received(t0 + 10 * MS);
        assert_eq!(h.last_received(), t0 + 1000 * MS);
    }

    #[test]
    fn custom_timings() {
        let t0 = Instant::now();
        let mut h = HeartbeatMonitor::new(t0, 10 * MS, 30 * MS);
        h.on_sent(t0);
        assert!(h.due(t0 + 10 * MS));
        assert!(h.timed_out(t0 + 30 * MS));
    }
}
